        state[i] = 1
        if kind == 0:
            l, d = node[1], node[2]
            if not isinstance(l, int) or isinstance(l, bool) or not (0 <= l < m):
                return False
            if d not in (0, 1):
                return False
            u, v, _c = links[l]
            st[i], en[i] = (u, v) if d == 0 else (v, u)
            seq[i] = [(l, d)]
        elif kind == 1:
            a, b = node[1], node[2]
            for x in (a, b):
                if not isinstance(x, int) or isinstance(x, bool) or not (0 <= x < len(recipes)):
                    return False
            if not resolve(a) or not resolve(b):
                return False
            if en[a] != st[b]:
                return False
            if en[a] in pc:
                return False
            st[i], en[i] = st[a], en[b]
            seq[i] = seq[a] + seq[b]
        else:
            return False
        state[i] = 2
        return True

    for i in range(len(recipes)):
        if not resolve(i):
            return False, 'recipe node invalid'
